#> plots the 2D fsq for each bin
def fsq2D(run, folder, b_data):
    
    #> setting style
    plot.setStyle()
    
    #> plotting match
    for i, b in enumerate(b_data):
        
        #> value of the parameter
        val = run['info']['points'][folder][i]
        label = labels(folder)
        
        #> initializing plot # 'Source-Caustic Proximity [arcsec]'
        fig, ax = plt.subplots(1,1,figsize=(6,6))
        plot.styleAx(ax, xlabel=r'$\mathbf{\theta_{23}}$', 
                         ylabel=r'$\mathbf{\Delta\theta_{23}}$',
                         title=f'{label} = {val:.4g}', sky=False)
        
        # obs = ['t12', 't23', 't34', 'd2/d1', 'd3/d1', 'd4/d1', 'dt23', 'd01']
        
        #> getting mismatches
        quad = b['nims'] == 5
        dt23  = b['obs'][quad][:,6]
        t23  = b['obs'][quad][:,1]
        
        #> 
        ax.scatter(t23, dt23, alpha=0.01, c='0.2')
        
        plot.finish(fig, outFile=f'{folder}_dt23_bin{str(i).zfill(2)}_{val:.4g}', 
                         loc=f'../arrival_order/figures/mismatch/{folder}/')
    
    return





